// ISO 4217 currencies (P3-02 step 1) from data/iso4217.json, generated by
// scripts/generate-iso4217.mjs (ADR 0045). Only current codes with a minor
// unit can form Money; withdrawn codes (SLL) and codes whose minor unit is
// N.A. (XAU, XDR, ...) are listed but rejected by parseCurrencyCode.
import iso4217 from "../data/iso4217.json" with { type: "json" };
import { MoneyError } from "./errors.js";

declare const currencyBrand: unique symbol;

/** A current ISO 4217 alphabetic code with a minor unit (exponent). */
export type CurrencyCode = string & { readonly [currencyBrand]: true };

export interface CurrencyInfo {
  readonly code: string;
  /** ISO 4217 numeric code ("048"); null if the source has none. */
  readonly numeric: string | null;
  readonly name: string;
  /** Minor-unit exponent; null for N.A. and for withdrawn codes. */
  readonly exponent: number | null;
  readonly historical: boolean;
  /** Withdrawal date as published ("2023-12"); null while current. */
  readonly withdrawn: string | null;
}

export interface UsableCurrency extends CurrencyInfo {
  readonly code: CurrencyCode;
  readonly exponent: number;
  readonly historical: false;
}

export interface Iso4217Source {
  readonly dataset: string;
  readonly url: string;
  readonly commit: string;
  readonly commitDate: string;
  readonly upstream: readonly string[];
  readonly licence: string;
  readonly retrievedAt: string;
  readonly sha256: string;
}

/** Where data/iso4217.json came from. */
export const ISO4217_SOURCE: Iso4217Source = Object.freeze({
  ...iso4217.source,
  upstream: Object.freeze([...iso4217.source.upstream]),
});

const byCode: ReadonlyMap<string, CurrencyInfo> = new Map(
  iso4217.currencies.map((c): [string, CurrencyInfo] => [
    c.code,
    Object.freeze({
      code: c.code,
      numeric: c.numeric,
      name: c.name,
      exponent: c.exponent,
      historical: c.historical,
      withdrawn: c.withdrawn,
    }),
  ]),
);

const isUsable = (info: CurrencyInfo): info is UsableCurrency =>
  !info.historical && info.exponent !== null;

const usable: readonly UsableCurrency[] = Object.freeze(
  [...byCode.values()].filter(isUsable),
);

/** Everything the file holds about `code`, usable or not; undefined if unknown. */
export const currencyInfo = (code: string): CurrencyInfo | undefined =>
  byCode.get(code);

/** Current codes that can form Money, sorted by code. */
export const listCurrencies = (): readonly UsableCurrency[] => usable;

/**
 * Checks `input` is a current ISO 4217 code with a minor unit. Strict: three
 * uppercase letters, no trimming. Throws MoneyError invalid_currency,
 * historical_currency or no_minor_unit; the message never holds the input.
 */
export function parseCurrencyCode(input: unknown): CurrencyCode {
  const info = typeof input === "string" ? byCode.get(input) : undefined;
  if (info === undefined) throw new MoneyError("invalid_currency");
  if (info.historical) throw new MoneyError("historical_currency");
  if (!isUsable(info)) throw new MoneyError("no_minor_unit");
  return info.code;
}

export function isCurrencyCode(input: unknown): input is CurrencyCode {
  const info = typeof input === "string" ? byCode.get(input) : undefined;
  return info !== undefined && isUsable(info);
}

/** The minor-unit exponent: JPY 0, USD 2, BHD 3, CLF 4. */
export function currencyExponent(code: CurrencyCode): number {
  const info = byCode.get(code);
  if (info === undefined || !isUsable(info))
    throw new MoneyError("invalid_currency");
  return info.exponent;
}
